import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = re.compile(r'https?://[^\s]+')
    urls = url_pattern.findall(myString)
    result = {}
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        domain = parsed.netloc
        if domain not in result:
            try:
                response = requests.get(f'https://api.ipapi.com/{domain}?access_key={API_KEY}')
                if response.status_code == 200:
                    result[domain] = response.json()
                else:
                    result[domain] = None
            except:
                result[domain] = None
    return result

