            urls.extend(re.findall(url_pattern, obj))
        elif isinstance(obj, dict):
            for v in obj.values():
                extract_strings(v)
        elif isinstance(obj, list):
            for item in obj:
                extract_strings(item)
    extract_strings(data)
    return dict(Counter(urls))
