import seaborn as sns
import pandas as pd

def task_func(json_data: str, key_path: list):
    data = json.loads(json_data)
    for key in key_path:
        if isinstance(data, dict):
            if key not in data:
                raise KeyError(f"Key '{key}' not found.")
            data = data[key]
        else:
            raise KeyError(f"Key '{key}' not found.")

