        if data.strip() == '':
            raise ValueError("The data string is empty.")
        try:
            nums = [float(x) for x in data.split(',') if x.strip()]
        except ValueError:
            raise ValueError("The data string is corrupted or contains non-numeric values.")
        if len(nums) == 0:
            raise ValueError("No numeric data found.")
    elif isinstance(data, list):
        nums = []
        for item in data:
            try:
                nums.append(float(item))
            except (ValueError, TypeError):
                raise ValueError("No numeric data found.")
        if len(nums) == 0:
            raise ValueError("No numeric data found.")
    else:
        raise ValueError("No numeric data found.")

    fig, ax = plt.subplots()
    sns.boxplot(data=nums, ax=ax)
    ax.set_title(f"Boxplot of data from key path: {'.'.join(key_path)}")
    return fig
